import{_ as r,o as i,c as a,a2 as s}from"./chunks/framework.ChIlRNAd.js";const d=JSON.parse('{"title":"Vie privée","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy.md","filePath":"fr/guide/privacy.md"}'),t={name:"fr/guide/privacy.md"};function n(l,e,o,c,f,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="vie-privee" tabindex="-1">Vie privée <a class="header-anchor" href="#vie-privee" aria-label="Permalink to &quot;Vie privée&quot;">​</a></h1><p>Nid peut chiffrer vos archives. Les images distantes (et les pixels espions qu&#39;elles cachent) sont bloquées par le lecteur tant que vous ne les affichez pas.</p><hr><h2 id="chiffrement-des-archives" tabindex="-1">Chiffrement des archives <a class="header-anchor" href="#chiffrement-des-archives" aria-label="Permalink to &quot;Chiffrement des archives&quot;">​</a></h2><p>Vos archives EML peuvent être chiffrées sur le NAS avec un algorithme <strong>AES-256-GCM</strong> (le même standard utilisé par les banques et gouvernements).</p><h3 id="configurer-le-chiffrement" tabindex="-1">Configurer le chiffrement <a class="header-anchor" href="#configurer-le-chiffrement" aria-label="Permalink to &quot;Configurer le chiffrement&quot;">​</a></h3><ol><li>Dans l&#39;onglet <strong>Chiffrement</strong>, cliquez sur <strong>Configurer</strong></li><li>Choisissez une <strong>phrase secrète</strong> (passphrase)</li><li>Confirmez la phrase secrète</li><li>Cliquez sur <strong>Activer le chiffrement</strong></li></ol><blockquote><p>📸 <em>Capture d&#39;écran suggérée : formulaire de configuration du chiffrement avec le champ passphrase</em></p></blockquote><div class="warning custom-block"><p class="custom-block-title">Conservez votre phrase secrète</p><p>La phrase secrète n&#39;est <strong>jamais stockée</strong> dans l&#39;application — seul un hash de vérification est conservé. Si vous la perdez, il sera impossible de déchiffrer vos archives. Notez-la dans un endroit sûr (gestionnaire de mots de passe, etc.).</p></div><h3 id="chiffrer-les-archives-existantes" tabindex="-1">Chiffrer les archives existantes <a class="header-anchor" href="#chiffrer-les-archives-existantes" aria-label="Permalink to &quot;Chiffrer les archives existantes&quot;">​</a></h3><p>Après avoir configuré la passphrase :</p><ol><li>Cliquez sur <strong>Chiffrer les archives</strong></li><li>Un job de chiffrement est lancé</li><li>Chaque fichier EML est chiffré individuellement sur le disque</li></ol><p>Les mails déjà chiffrés sont automatiquement ignorés (idempotent).</p><h3 id="lire-un-mail-chiffre" tabindex="-1">Lire un mail chiffré <a class="header-anchor" href="#lire-un-mail-chiffre" aria-label="Permalink to &quot;Lire un mail chiffré&quot;">​</a></h3><p>Quand vous consultez un mail chiffré dans la page Archives, il est <strong>déchiffré à la volée</strong> dans la mémoire du serveur. Le fichier reste chiffré sur le disque en permanence.</p><h3 id="statut-du-chiffrement" tabindex="-1">Statut du chiffrement <a class="header-anchor" href="#statut-du-chiffrement" aria-label="Permalink to &quot;Statut du chiffrement&quot;">​</a></h3><p>L&#39;onglet Chiffrement affiche :</p><ul><li>Si une passphrase est configurée</li><li>Le nombre de mails chiffrés / non chiffrés</li><li>Un indicateur de sécurité global</li></ul><blockquote><p>📸 <em>Capture d&#39;écran suggérée : statut du chiffrement avec le nombre de mails chiffrés et le pourcentage</em></p></blockquote>',19)])])}const p=r(t,[["render",n]]);export{d as __pageData,p as default};
